+import { createPool } from "mysql2";
+import { Pool } from "pg";
+import * as fs from "fs";
+import * as path from "path";
+
+interface ColumnInfo {
+  name: string;
+  type: string;
+  nullable: boolean;
+  hasDefault: boolean;
+}
+
+interface TableInfo {
+  name: string;
+  columns: ColumnInfo[];
+}
+
+async function introspectPostgres(): Promise<TableInfo[]> {
+  const pool = new Pool({ connectionString: process.env.DATABASE_URL });
+
+  try {
+    const result = await pool.query(`
+      SELECT
+        t.table_name,
+        c.column_name,
+        c.data_type,
+        c.is_nullable,
+        c.column_default IS NOT NULL as has_default
+      FROM information_schema.tables t
+      JOIN information_schema.columns c ON t.table_name = c.table_name
+      WHERE t.table_schema = 'public'
+      ORDER BY t.table_name, c.ordinal_position
+    `);
+
+    const tableMap = new Map<string, TableInfo>();
+
+    for (const row of result.rows) {
+      if (!tableMap.has(row.table_name)) {
+        tableMap.set(row.table_name, { name: row.table_name, columns: [] });
+      }
+
+      const table = tableMap.get(row.table_name)!;
+      table.columns.push({
+        name: row.column_name,
+        type: row.data_type,
+        nullable: row.is_nullable === "YES",
+        hasDefault: row.has_default,
+      });
+    }
+
+    return Array.from(tableMap.values());
+  } finally {
+    await pool.end();
+  }
+}
+
+function pgTypeToTS(pgType: string, nullable: boolean, hasDefault: boolean): string {
+  let tsType: string;
+
+  switch (pgType.toLowerCase()) {
+    case "character varying":
+    case "varchar":
+    case "text":
+    case "char":
+      tsType = "string";
+      break;
+    case "integer":
+    case "smallint":
+    case "bigint":
+      tsType = "number";
+      break;
+    case "boolean":
+      tsType = "boolean";
+      break;
+    case "timestamp":
+    case "timestamp without time zone":
+    case "timestamp with time zone":
+    case "date":
+      tsType = "Date";
+      break;
+    case "numeric":
+    case "decimal":
+    case "real":
+    case "double precision":
+      tsType = "number";
+      break;
+    case "json":
+    case "jsonb":
+      tsType = "any";
+      break;
+    case "uuid":
+      tsType = "string";
+      break;
+    default:
+      tsType = "any";
+  }
+
+  if (nullable && !hasDefault) {
+    tsType += " | null";
+  }
+
+  return tsType;
+}
+
+function isGeneratedColumn(column: ColumnInfo): boolean {
+  return (
+    (column.name === "id" && column.type === "uuid") ||
+    (column.name === "id" && column.type === "integer") ||
+    column.name.endsWith("_at") ||
+    column.hasDefault
+  );
+}
+
+async function generateSchema(tables: TableInfo[]): Promise<string> {
+  let output = `import { Generated, Insertable, Selectable, Updateable } from 'kysely';
+
+`;
+
+  for (const table of tables) {
+    const interfaceName = pascalCase(table.name) + "Table";
+
+    output += `export interface ${interfaceName} {
+`;
+
+    for (const column of table.columns) {
+      const isGenerated = isGeneratedColumn(column);
+      const baseType = pgTypeToTS(column.type, column.nullable, column.hasDefault);
+
+      if (isGenerated) {
+        output += `  ${column.name}: Generated<${baseType}>;
+`;
+      } else {
+        output += `  ${column.name}: ${baseType};
+`;
+      }
+    }
+
+    output += `}
+
+`;
+  }
+
+  output += `export interface Database {
+`;
+  for (const table of tables) {
+    const interfaceName = pascalCase(table.name) + "Table";
+    output += `  ${table.name}: ${interfaceName};
+`;
+  }
+  output += `}
+
+`;
+
+  for (const table of tables) {
+    const interfaceName = pascalCase(table.name) + "Table";
+    const singularName = singularize(table.name);
+
+    output += `export type ${pascalCase(singularName)} = Selectable<${interfaceName}>;
+export type New${pascalCase(singularName)} = Insertable<${interfaceName}>;
+export type ${pascalCase(singularName)}Update = Updateable<${interfaceName}>;
+
+`;
+  }
+
+  return output;
+}
+
+function pascalCase(str: string): string {
+  return str
+    .split("_")
+    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
+    .join("");
+}
+
+function singularize(str: string): string {
+  if (str.endsWith("ies")) {
+    return str.slice(0, -3) + "y";
+  }
+  if (str.endsWith("ses")) {
+    return str.slice(0, -2);
+  }
+  if (str.endsWith("s")) {
+    return str.slice(0, -1);
+  }
+  return str;
+}
+
+async function main() {
+  console.log("Introspecting Postgres schema...");
+  const tables = await introspectPostgres();
+  console.log(`Found ${tables.length} tables`);
+
+  const schema = await generateSchema(tables);
+  const outputPath = path.join(__dirname, "schema.ts");
+
+  fs.writeFileSync(outputPath, schema);
+  console.log(`Generated schema.ts at ${outputPath}`);
+}
+
+main().catch(console.error);
